#!/usr/bin/env node
// Deterministic computed-style & DOM QA auditor for cupertino-forge.
// Reads ALL design thresholds from cupertino.tokens.resolved.json (generated by build-tokens.mjs).
// Never hardcodes token values; reports unrun checks as NOT RUN (<reason>), never OK.
//
// Usage:
//   node qa/computed-style-audit.mjs --url <url-or-file> [--tokens <resolved.json>] [--platform ios|macos] [--theme light|dark] [--accent <#HEX>] [--json] [--out <file>]
// Exit codes:
//   0 = 0 failures (may still contain NOT RUN when browser unavailable)
//   1 = 1+ FAIL checks
//   2 = CLI usage error or target load error

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(__dirname, '..');

function parseArgs(argv) {
  const opts = { platform: 'ios', accent: '#0088FF', json: false };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--json') opts.json = true;
    else if (a === '--url') opts.url = argv[++i];
    else if (a === '--tokens') opts.tokens = argv[++i];
    else if (a === '--platform') {
      const p = argv[++i];
      opts.platform = p === 'mac' ? 'macos' : p;
    }
    else if (a === '--accent') opts.accent = argv[++i];
    else if (a === '--out') opts.out = argv[++i];
    else if (a === '--theme') opts.theme = argv[++i];
  }
  return opts;
}

function normalizeUrl(raw) {
  if (!raw) return null;
  if (/^(https?|file):\/\//i.test(raw)) return raw;
  return pathToFileURL(path.resolve(raw)).href;
}

function loadResolvedTokens(tokensPath, accent) {
  if (tokensPath) {
    return { tokens: JSON.parse(fs.readFileSync(path.resolve(tokensPath), 'utf8')), cleanup: () => {} };
  }
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'cf-qa-tokens-'));
  const buildScript = path.join(repoRoot, 'scripts', 'build-tokens.mjs');
  const res = spawnSync(
    process.execPath,
    [buildScript, '--out', tmpDir, '--targets', 'json', '--accent', accent],
    { encoding: 'utf8' }
  );
  if (res.status !== 0) {
    fs.rmSync(tmpDir, { recursive: true, force: true });
    throw new Error(`build-tokens.mjs failed: ${res.stderr || res.stdout}`);
  }
  const jsonPath = path.join(tmpDir, 'cupertino.tokens.resolved.json');
  return {
    tokens: JSON.parse(fs.readFileSync(jsonPath, 'utf8')),
    cleanup: () => fs.rmSync(tmpDir, { recursive: true, force: true }),
  };
}

function buildNotRunReport(targetUrl, platform, reason, tokensMeta) {
  const specs = [
    ['font-size', 'measured', 'typography'],
    ['letter-spacing', 'measured', 'typography'],
    ['border-radius', 'estimate-based', 'shape'],
    ['spacing-grid', 'estimate-based', 'layout.spacing'],
    ['hit-target', 'official', 'layout.hitTarget'],
    ['contrast', 'official', 'tokens/color.json (HIG)'],
    ['glass-budget', 'estimate-based', 'materials.perfBudget'],
    ['glass-translucency', 'official', 'materials.liquidGlass'],
    ['focus-ring', 'measured', 'colors.focusRing'],
    ['raw-color', 'measured', 'colors + materials'],
    ['easing', 'estimate-based', 'motion.springs'],
    ['reduced-motion', 'official', 'motion (prefers-reduced-motion)'],
  ];
  const checks = specs.map(([id, basis, sourceToken]) => ({
    id,
    status: 'NOT RUN',
    basis,
    sourceToken,
    detail: reason,
    violations: [],
  }));
  return {
    url: targetUrl,
    platform,
    accent: tokensMeta?.accent || null,
    summary: { pass: 0, fail: 0, notRun: checks.length, score: null },
    checks,
  };
}

async function launchChromium(playwright) {
  const attempts = [
    { label: 'chromium', opts: { headless: true, args: ['--no-sandbox'] } },
    { label: 'chrome', opts: { headless: true, channel: 'chrome', args: ['--no-sandbox'] } },
    { label: 'msedge', opts: { headless: true, channel: 'msedge', args: ['--no-sandbox'] } },
  ];
  const errors = [];
  for (const a of attempts) {
    try {
      const browser = await playwright.chromium.launch(a.opts);
      return { browser, engine: a.label };
    } catch (err) {
      errors.push(`${a.label}: ${err.message.split('\n')[0]}`);
    }
  }
  throw new Error(`Playwright Chromium unavailable (${errors.join('; ')})`);
}

async function runAudit(targetUrl, tokens, platform, theme) {
  let pw;
  try {
    pw = await import('playwright');
  } catch (err) {
    return buildNotRunReport(
      targetUrl,
      platform,
      `Playwright package not installed in qa/ (${err.code || err.message}); run npm install inside qa/`,
      tokens.$meta
    );
  }

  let browser;
  let engineName = 'chromium';
  try {
    const launched = await launchChromium(pw);
    browser = launched.browser;
    engineName = launched.engine;
  } catch (err) {
    return buildNotRunReport(targetUrl, platform, err.message, tokens.$meta);
  }

  try {
    const viewport = platform === 'macos' ? { width: 1280, height: 800 } : { width: 390, height: 844 };
    const context = await browser.newContext({ viewport, ...(theme ? { colorScheme: theme } : {}) });
    if (theme) {
      await context.addInitScript((t) => {
        try { localStorage.setItem('cf-theme', t); } catch { /* storage unavailable on file:// in some engines */ }
        document.documentElement.dataset.theme = t;
      }, theme);
    }
    const page = await context.newPage();

    // Normalize OS prefers-reduced-transparency to no-preference for deterministic baseline auditing
    // (explicit in-app data-transparency="reduce", data-contrast="more", or forced-colors still silence glass-translucency)
    try {
      const cdp = await context.newCDPSession(page);
      await cdp.send('Emulation.setEmulatedMedia', {
        features: [
          { name: 'prefers-reduced-transparency', value: 'no-preference' },
          ...(theme ? [{ name: 'prefers-color-scheme', value: theme }] : []),
        ],
      });
    } catch { /* non-CDP engine fallback */ }

    await page.goto(targetUrl, { waitUntil: 'networkidle' });
    await page.waitForTimeout(120);

    const domData = await page.evaluate(({ tokens: tok, plat }) => {
      const parseCssColor = (str) => {
        if (!str || typeof str !== 'string') return null;
        // Standard rgb() / rgba()
        const m = str.match(/rgba?\(\s*([\d.]+)\s*[,\s]\s*([\d.]+)\s*[,\s]\s*([\d.]+)(?:\s*[,/]\s*([\d.]+%?))?\s*\)/i);
        if (m) {
          let a = 1;
          if (m[4] !== undefined) {
            a = m[4].endsWith('%') ? parseFloat(m[4]) / 100 : parseFloat(m[4]);
          }
          return { r: Math.round(+m[1]), g: Math.round(+m[2]), b: Math.round(+m[3]), a };
        }
        // CSS Color 4 color(srgb r g b / a) (emitted by Chromium for color-mix)
        const m4 = str.match(/color\(\s*(?:srgb|display-p3)\s+([\d.]+)\s+([\d.]+)\s+([\d.]+)(?:\s*\/\s*([\d.]+%?))?\s*\)/i);
        if (m4) {
          let a = 1;
          if (m4[4] !== undefined) {
            a = m4[4].endsWith('%') ? parseFloat(m4[4]) / 100 : parseFloat(m4[4]);
          }
          return {
            r: Math.round(Math.max(0, Math.min(1, parseFloat(m4[1]))) * 255),
            g: Math.round(Math.max(0, Math.min(1, parseFloat(m4[2]))) * 255),
            b: Math.round(Math.max(0, Math.min(1, parseFloat(m4[3]))) * 255),
            a,
          };
        }
        return null;
      };

      const parseTokenHex = (str) => {
        if (typeof str !== 'string') return null;
        if (str.startsWith('rgba(') || str.startsWith('rgb(') || str.startsWith('color(')) return parseCssColor(str);
        const m = str.match(/^#([0-9a-fA-F]{6})(?:@([\d.]+))?$/);
        if (!m) return null;
        const n = parseInt(m[1], 16);
        return {
          r: (n >> 16) & 255,
          g: (n >> 8) & 255,
          b: n & 255,
          a: m[2] !== undefined ? parseFloat(m[2]) : 1,
        };
      };

      const allowedRgba = [];
      const collectColors = (node) => {
        if (!node) return;
        if (typeof node === 'string') {
          const c = parseTokenHex(node.trim());
          if (c) allowedRgba.push(c);
          return;
        }
        if (Array.isArray(node)) {
          node.forEach(collectColors);
          return;
        }
        if (typeof node === 'object') {
          for (const [k, v] of Object.entries(node)) {
            if (k === '$url' || k === '$source' || k === '$usage' || k === '$platform' || k === '$class') continue;
            collectColors(v);
          }
        }
      };
      collectColors(tok.colors);
      collectColors(tok.$meta?.accent);
      collectColors(tok.materials);

      // Official Apple secondary label tokens (e.g. #3C3C43@0.6 = 3.44:1 on #FFFFFF in light mode)
      const secondaryLabelTokens = [
        parseTokenHex(tok.colors?.labelIOS?.secondary?.light),
        parseTokenHex(tok.colors?.labelIOS?.secondary?.dark),
        parseTokenHex(tok.colors?.labelMacOS?.secondary?.light),
        parseTokenHex(tok.colors?.labelMacOS?.secondary?.dark),
      ].filter(Boolean);

      const isOfficialSecondaryLabel = (c) =>
        secondaryLabelTokens.some(
          (t) =>
            Math.abs(t.r - c.r) <= 3 &&
            Math.abs(t.g - c.g) <= 3 &&
            Math.abs(t.b - c.b) <= 3 &&
            Math.abs(t.a - c.a) <= 0.05
        );

      const accentTokens = [
        parseTokenHex(tok.$meta?.accent?.light),
        parseTokenHex(tok.$meta?.accent?.dark),
      ].filter(Boolean);

      const isWhiteOnOfficialAccent = (fgC, bgC) =>
        fgC.r >= 250 && fgC.g >= 250 && fgC.b >= 250 &&
        accentTokens.some(
          (t) => Math.abs(t.r - bgC.r) <= 3 && Math.abs(t.g - bgC.g) <= 3 && Math.abs(t.b - bgC.b) <= 3
        );

      const matchesTokenColor = (cssStr) => {
        const c = parseCssColor(cssStr);
        if (!c) return true;
        if (c.a === 0) return true;
        return allowedRgba.some(
          (t) => Math.abs(t.r - c.r) <= 3 && Math.abs(t.g - c.g) <= 3 && Math.abs(t.b - c.b) <= 3
        );
      };

      const blendOver = (fg, bg) => {
        const a = fg.a + bg.a * (1 - fg.a);
        if (a <= 0) return { r: 255, g: 255, b: 255, a: 1 };
        return {
          r: (fg.r * fg.a + bg.r * bg.a * (1 - fg.a)) / a,
          g: (fg.g * fg.a + bg.g * bg.a * (1 - fg.a)) / a,
          b: (fg.b * fg.a + bg.b * bg.a * (1 - fg.a)) / a,
          a,
        };
      };

      const relLuminance = ({ r, g, b }) => {
        const chan = (v) => {
          const s = v / 255;
          return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
        };
        return 0.2126 * chan(r) + 0.7152 * chan(g) + 0.0722 * chan(b);
      };

      const contrastRatio = (c1, c2) => {
        const l1 = relLuminance(c1);
        const l2 = relLuminance(c2);
        return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
      };

      const isDarkDoc = document.documentElement.dataset.theme === 'dark';
      const defaultCanvas = parseTokenHex(
        isDarkDoc ? tok.colors.backgroundIOS.primary.dark : tok.colors.backgroundIOS.primary.light
      ) || { r: 255, g: 255, b: 255, a: 1 };

      const effectiveBackground = (el) => {
        const chain = [];
        for (let cur = el; cur; cur = cur.parentElement) {
          const bg = parseCssColor(getComputedStyle(cur).backgroundColor);
          if (bg && bg.a > 0) chain.push(bg);
        }
        let acc = { ...defaultCanvas, a: 1 };
        for (let i = chain.length - 1; i >= 0; i--) {
          acc = blendOver(chain[i], acc);
        }
        return acc;
      };

      const effectiveHitRect = (el, rect, platMode) => {
        let w = rect.width;
        let h = rect.height;
        if (platMode === 'macos') {
          const role = el.getAttribute('role') || '';
          if (role === 'checkbox' || role === 'radio') {
            const lbl = el.closest('label');
            if (lbl) {
              const lr = lbl.getBoundingClientRect();
              w = Math.max(w, lr.width);
              h = Math.max(h, lr.height);
            }
          }
        }
        for (const pseudo of ['::after', '::before']) {
          const pcs = getComputedStyle(el, pseudo);
          if (!pcs || pcs.content === 'none' || pcs.content === 'normal') continue;
          if (pcs.position !== 'absolute') continue;
          const pw = parseFloat(pcs.width);
          const ph = parseFloat(pcs.height);
          if (!Number.isNaN(pw) && pw > w) w = pw;
          if (!Number.isNaN(ph) && ph > h) h = ph;
        }
        return { width: w, height: h };
      };

      const selectorFor = (el) => {
        if (el.id) return `#${el.id}`;
        const cls = typeof el.className === 'string' && el.className.trim()
          ? '.' + el.className.trim().split(/\s+/).slice(0, 2).join('.')
          : '';
        const defect = el.getAttribute('data-defect') ? `[data-defect="${el.getAttribute('data-defect')}"]` : '';
        return `${el.tagName.toLowerCase()}${cls}${defect}`;
      };

      const isVisible = (el) => {
        const cs = getComputedStyle(el);
        if (cs.display === 'none' || cs.visibility === 'hidden' || parseFloat(cs.opacity) === 0) return false;
        const r = el.getBoundingClientRect();
        return r.width > 0 && r.height > 0;
      };

      const hasDirectText = (el) => {
        for (const n of el.childNodes) {
          if (n.nodeType === Node.TEXT_NODE && n.nodeValue && n.nodeValue.trim().length > 0) return true;
        }
        return false;
      };

      // Build scale tables purely from tokens
      const typeMap = plat === 'macos' ? tok.typography.macos : tok.typography.iosLarge;
      const typeEntries = Object.entries(typeMap)
        .filter(([k, v]) => !k.startsWith('$') && v && typeof v === 'object' && typeof v.size === 'number')
        .map(([k, v]) => ({ name: k, size: v.size, trackingPx: v.trackingPx ?? 0, trackingEm: v.trackingEm ?? 0 }));
      const interDeltaEm = tok.typography.fallbackCompensation?.inter?.trackingDeltaEm ?? 0;
      const useInter = document.documentElement.dataset.cfFont === 'inter';
      const disableLangs = new Set(tok.typography.nonLatin?.disableTrackingLangs || ['bn', 'ar', 'he']);

      const shapeObj = plat === 'macos' ? tok.shape.radiusMacOS : tok.shape.radiusIOS;
      const allowedRadii = new Set([0]);
      if (typeof tok.shape.concentric?.minimumInner === 'number') allowedRadii.add(tok.shape.concentric.minimumInner);
      const collectRadii = (o) => {
        for (const [k, v] of Object.entries(o || {})) {
          if (k.startsWith('$')) continue;
          if (typeof v === 'number') allowedRadii.add(v);
          else if (v && typeof v === 'object') collectRadii(v);
        }
      };
      collectRadii(shapeObj);

      const spacingScale = new Set(tok.layout.spacing.scale || []);
      const hitMin = plat === 'macos'
        ? (tok.layout.hitTarget.macosMinimumClickable ?? tok.layout.hitTarget.macos)
        : tok.layout.hitTarget.ios;
      const glassBudgetMax = tok.materials.perfBudget?.maxSimultaneousBackdrop ?? 6;
      const maxFocusSize = 18;
      const boldWeightMin = 600;

      const solidFallbackActive =
        document.documentElement.dataset.transparency === 'reduce' ||
        document.documentElement.dataset.contrast === 'more' ||
        (document.documentElement.dataset.transparency !== 'normal' &&
          window.matchMedia('(prefers-reduced-transparency: reduce)').matches) ||
        window.matchMedia('(forced-colors: active)').matches ||
        window.matchMedia('(prefers-contrast: more)').matches;

      const fontViolations = [];
      const trackingViolations = [];
      const radiusViolations = [];
      const spacingViolations = [];
      const hitViolations = [];
      const contrastViolations = [];
      const contrastAdvisories = [];
      const rawColorViolations = [];
      const easingViolations = [];
      const glassNodes = [];
      const glassTranslucencyViolations = [];

      const forbiddenTimingRe = /^(ease|ease-in|ease-out|ease-in-out|linear)$/i;
      const canonicalCubicRe = /^(cubic-bezier\(\s*0\.25\s*,\s*0\.1\s*,\s*0\.25\s*,\s*1\s*\)|cubic-bezier\(\s*0\.42\s*,\s*0\s*,\s*1\s*,\s*1\s*\)|cubic-bezier\(\s*0\s*,\s*0\s*,\s*0\.58\s*,\s*1\s*\)|cubic-bezier\(\s*0\.42\s*,\s*0\s*,\s*0\.58\s*,\s*1\s*\))$/i;

      const skipTags = new Set(['HTML', 'HEAD', 'SCRIPT', 'STYLE', 'META', 'LINK', 'TITLE', 'NOSCRIPT', 'BR', 'SVG', 'PATH', 'CIRCLE', 'RECT', 'LINE']);
      const allEls = Array.from(document.querySelectorAll('*')).filter((el) => !skipTags.has(el.tagName) && isVisible(el));

      for (const el of allEls) {
        const cs = getComputedStyle(el);
        const rect = el.getBoundingClientRect();
        const sel = selectorFor(el);

        // 1 & 2. Font-size & letter-spacing (for elements with direct visible text)
        if (hasDirectText(el)) {
          const fs = parseFloat(cs.fontSize);
          const matchedStyles = typeEntries.filter((t) => Math.abs(t.size - fs) <= 0.5);
          if (matchedStyles.length === 0) {
            fontViolations.push({ selector: sel, actual: `${fs}px`, expected: `one of [${[...new Set(typeEntries.map((t) => t.size))].join(', ')}]px` });
          } else {
            const langEl = el.closest('[lang]');
            const langCode = (langEl?.getAttribute('lang') || '').toLowerCase().split('-')[0];
            const lsRaw = cs.letterSpacing;
            const ls = lsRaw === 'normal' ? 0 : parseFloat(lsRaw);
            if (!Number.isNaN(ls)) {
              if (disableLangs.has(langCode)) {
                if (Math.abs(ls) > 0.15) {
                  trackingViolations.push({ selector: sel, actual: `${ls}px (:lang(${langCode}))`, expected: '0px for bn/ar/he' });
                }
              } else {
                const okTracking = matchedStyles.some((st) => {
                  const baseOk = Math.abs(ls - st.trackingPx) <= 0.35;
                  const interOk = useInter && Math.abs(ls - (st.trackingPx + st.size * interDeltaEm)) <= 0.35;
                  return baseOk || interOk;
                });
                if (!okTracking) {
                  const expectedList = matchedStyles.map((st) => `${st.trackingPx}px`).join(' | ');
                  trackingViolations.push({ selector: sel, actual: `${ls.toFixed(2)}px @ ${fs}px`, expected: expectedList });
                }
              }
            }
          }

          // 6. Contrast
          const fg = parseCssColor(cs.color);
          if (fg) {
            const bg = effectiveBackground(el);
            const effFg = blendOver(fg, bg);
            const ratio = contrastRatio(effFg, bg);
            const weight = parseInt(cs.fontWeight, 10) || 400;
            const minRatio = fs < maxFocusSize && weight < boldWeightMin ? 4.5 : 3.0;
            if (ratio + 0.05 < minRatio) {
              if (isOfficialSecondaryLabel(fg) && ratio >= 3.0) {
                contrastAdvisories.push({
                  selector: sel,
                  actual: `${ratio.toFixed(2)}:1 (official Apple secondary label token)`,
                  expected: `>= 4.5:1 (HC raises to lightHC/darkHC)`,
                });
              } else if (plat === 'macos' && isWhiteOnOfficialAccent(effFg, bg) && ratio >= 3.0) {
                contrastAdvisories.push({
                  selector: sel,
                  actual: `${ratio.toFixed(2)}:1 (white on official Apple system accent)`,
                  expected: `>= 4.5:1 (macOS 13pt regular selection/button trade-off)`,
                });
              } else {
                contrastViolations.push({
                  selector: sel,
                  actual: `${ratio.toFixed(2)}:1 (fontSize=${fs}px, weight=${weight})`,
                  expected: `>= ${minRatio}:1`,
                });
              }
            }
          }
        }

        // 3. Border-radius
        const cornerProps = [cs.borderTopLeftRadius, cs.borderTopRightRadius, cs.borderBottomRightRadius, cs.borderBottomLeftRadius];
        const minSide = Math.min(rect.width, rect.height);
        for (const rStr of cornerProps) {
          const rVal = parseFloat(rStr) || 0;
          if (rVal === 0) continue;
          const isCapsuleOrCircle = rVal >= 999 || rVal >= (minSide / 2) - 0.5;
          const matchesToken = Array.from(allowedRadii).some((ar) => Math.abs(ar - rVal) <= 1.0);
          if (!isCapsuleOrCircle && !matchesToken) {
            radiusViolations.push({
              selector: sel,
              actual: `${rVal}px`,
              expected: `token radius [${Array.from(allowedRadii).sort((a, b) => a - b).join(', ')}]px or capsule`,
            });
            break;
          }
        }

        // 4. 4pt spacing grid (estimate-based)
        const spacingVals = [
          ['paddingTop', cs.paddingTop],
          ['paddingRight', cs.paddingRight],
          ['paddingBottom', cs.paddingBottom],
          ['paddingLeft', cs.paddingLeft],
          ['marginTop', cs.marginTop],
          ['marginBottom', cs.marginBottom],
          ['rowGap', cs.rowGap === 'normal' ? '0px' : cs.rowGap],
          ['columnGap', cs.columnGap === 'normal' ? '0px' : cs.columnGap],
        ];
        for (const [prop, raw] of spacingVals) {
          const val = parseFloat(raw);
          if (!val || val === 0) continue;
          const onGrid = Math.abs(val % 4) <= 0.25 || (Math.abs(val - Math.round(val)) <= 0.25 && spacingScale.has(Math.round(val))) || Math.abs(val - 1) <= 0.1;
          if (!onGrid) {
            spacingViolations.push({ selector: sel, actual: `${prop}: ${val}px`, expected: '4px grid or layout.spacing.scale' });
            break;
          }
        }

        // 5. Hit-target size (accounts for ::after / ::before hit-area extenders)
        const interactiveRe = /^(BUTTON|INPUT|SELECT|TEXTAREA|A)$/i;
        const role = el.getAttribute('role') || '';
        const isInteractive =
          (interactiveRe.test(el.tagName) && el.getAttribute('type') !== 'hidden' && (el.tagName !== 'A' || el.hasAttribute('href'))) ||
          ['button', 'tab', 'switch', 'checkbox', 'radio', 'menuitem'].includes(role);
        if (isInteractive && !el.closest('p')) {
          const hit = effectiveHitRect(el, rect, plat);
          if (hit.width + 0.5 < hitMin || hit.height + 0.5 < hitMin) {
            hitViolations.push({
              selector: sel,
              actual: `${Math.round(hit.width)}x${Math.round(hit.height)}px`,
              expected: `>= ${hitMin}x${hitMin}px`,
            });
          }
        }

        // 7 & 8. Simultaneous visible glass count & glass translucency (solid override detection)
        const bf = (cs.backdropFilter && cs.backdropFilter !== 'none') ? cs.backdropFilter : (cs.webkitBackdropFilter && cs.webkitBackdropFilter !== 'none' ? cs.webkitBackdropFilter : 'none');
        const isGlassEl = el.classList.contains('cf-glass') || bf !== 'none';
        if (bf !== 'none' && rect.bottom > 0 && rect.top < window.innerHeight && rect.right > 0 && rect.left < window.innerWidth) {
          glassNodes.push(sel);
        }
        if (isGlassEl && !solidFallbackActive) {
          const gBg = parseCssColor(cs.backgroundColor);
          if (gBg && gBg.a >= 0.95) {
            glassTranslucencyViolations.push({
              selector: sel,
              actual: `backgroundColor=${cs.backgroundColor} (alpha=${gBg.a.toFixed(2)})`,
              expected: 'translucent glass background (alpha < 0.95) outside reduce-transparency/forced-colors',
            });
          }
        }

        // 9. Raw / non-token colors
        if (hasDirectText(el) && !matchesTokenColor(cs.color)) {
          rawColorViolations.push({ selector: sel, actual: `color: ${cs.color}`, expected: 'color token from cupertino.tokens.resolved.json' });
        }
        const bgC = parseCssColor(cs.backgroundColor);
        if (bgC && bgC.a > 0 && !matchesTokenColor(cs.backgroundColor)) {
          rawColorViolations.push({ selector: sel, actual: `background-color: ${cs.backgroundColor}`, expected: 'surface/fill/system token from cupertino.tokens.resolved.json' });
        }

        // 10. Non-spring easing timing functions (only when transitionDuration > 0 or animationName != none)
        const durMs = (s) => (s || '').split(',').some((d) => {
          const t = d.trim();
          const v = parseFloat(t);
          return !Number.isNaN(v) && v > 0;
        });
        const checkTimingList = (listStr, kind) => {
          for (const part of listStr.split(/,(?![^(]*\))/)) {
            const p = part.trim();
            if (/^linear\(/i.test(p)) continue; // sampled spring linear(...) is allowed
            if (forbiddenTimingRe.test(p) || canonicalCubicRe.test(p)) {
              easingViolations.push({
                selector: sel,
                actual: `${kind}: ${p}`,
                expected: 'spring linear(...) timing or Apple spring physics',
              });
              break;
            }
          }
        };
        if (durMs(cs.transitionDuration)) checkTimingList(cs.transitionTimingFunction, 'transitionTimingFunction');
        if (cs.animationName && cs.animationName !== 'none') checkTimingList(cs.animationTimingFunction, 'animationTimingFunction');
      }

      // Collect focusable controls for keyboard focus-ring pass
      const focusableEls = Array.from(
        document.querySelectorAll('button:not([disabled]), a[href], input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])')
      ).filter(isVisible);
      focusableEls.forEach((el, idx) => el.setAttribute('data-cf-qa-focus-idx', String(idx)));
      const unfocusedSnapshots = focusableEls.map((el) => {
        const cs = getComputedStyle(el);
        return {
          idx: el.getAttribute('data-cf-qa-focus-idx'),
          selector: selectorFor(el),
          outlineStyle: cs.outlineStyle,
          outlineWidth: parseFloat(cs.outlineWidth) || 0,
          boxShadow: cs.boxShadow,
        };
      });

      return {
        fontViolations,
        trackingViolations,
        radiusViolations,
        spacingViolations,
        hitViolations,
        contrastViolations,
        contrastAdvisories,
        rawColorViolations,
        easingViolations,
        glassNodes,
        glassBudgetMax,
        glassTranslucencyViolations,
        solidFallbackActive,
        hitMin,
        unfocusedSnapshots,
      };
    }, { tokens, plat: platform });

    // Keyboard focus-ring check via real sequential Tab traversal (:focus-visible guaranteed)
    const focusViolations = [];
    if (domData.unfocusedSnapshots.length > 0) {
      const snapByIdx = new Map(domData.unfocusedSnapshots.map((s) => [s.idx, s]));
      const seen = new Set();
      await page.mouse.click(1, 1).catch(() => {});
      const maxTabs = Math.min(domData.unfocusedSnapshots.length + 10, 80);
      for (let step = 0; step < maxTabs; step++) {
        await page.keyboard.press('Tab');
        const activeInfo = await page.evaluate(() => {
          const el = document.activeElement;
          if (!el || !el.hasAttribute('data-cf-qa-focus-idx')) return null;
          const cs = getComputedStyle(el);
          return {
            idx: el.getAttribute('data-cf-qa-focus-idx'),
            outlineStyle: cs.outlineStyle,
            outlineWidth: parseFloat(cs.outlineWidth) || 0,
            boxShadow: cs.boxShadow,
          };
        });
        if (!activeInfo) continue;
        if (seen.has(activeInfo.idx) && seen.size >= snapByIdx.size) break;
        if (seen.has(activeInfo.idx)) continue;
        seen.add(activeInfo.idx);
        const before = snapByIdx.get(activeInfo.idx);
        const hasOutline = activeInfo.outlineStyle !== 'none' && activeInfo.outlineWidth > 0;
        const gainedShadow = activeInfo.boxShadow !== 'none' && activeInfo.boxShadow !== before?.boxShadow;
        if (!hasOutline && !gainedShadow) {
          focusViolations.push({
            selector: before?.selector || `[focus-idx=${activeInfo.idx}]`,
            actual: `outline=${activeInfo.outlineStyle} ${activeInfo.outlineWidth}px, boxShadow=${activeInfo.boxShadow}`,
            expected: 'visible outline or focus-visible boxShadow ring (tokens/color.json focusRing)',
          });
        }
        if (seen.size >= snapByIdx.size) break;
      }
    }

    // Reduced-motion pass: emulate prefers-reduced-motion: reduce, trigger hover/press interactions,
    // and flag any running spatial/transform/scale/rotate animation (opacity cross-fades allowed).
    await page.emulateMedia({ reducedMotion: 'reduce' });
    await page.waitForTimeout(120);

    const sampleMotionViolations = async (phaseLabel) =>
      page.evaluate((phase) => {
        const MOTION_PROPS = new Set(['transform', 'translate', 'scale', 'rotate', 'top', 'left', 'right', 'bottom', 'x', 'y']);
        const selectorFor = (el) => {
          if (!el || el.nodeType !== 1) return 'unknown';
          if (el.id) return `#${el.id}`;
          const cls = typeof el.className === 'string' && el.className.trim()
            ? '.' + el.className.trim().split(/\s+/).slice(0, 2).join('.')
            : '';
          const defect = el.getAttribute('data-defect') ? `[data-defect="${el.getAttribute('data-defect')}"]` : '';
          return `${el.tagName.toLowerCase()}${cls}${defect}`;
        };
        const found = [];
        for (const anim of document.getAnimations()) {
          if (anim.playState !== 'running') continue;
          const effect = anim.effect;
          const target = effect && 'target' in effect ? effect.target : null;
          if (!target || target.nodeType !== 1) continue;
          const cs = getComputedStyle(target);
          if (cs.display === 'none' || cs.visibility === 'hidden') continue;
          const r = target.getBoundingClientRect();
          if (r.width === 0 || r.height === 0) continue;
          let animatedProps = [];
          if (typeof effect.getKeyframes === 'function') {
            for (const kf of effect.getKeyframes()) {
              for (const k of Object.keys(kf)) {
                if (MOTION_PROPS.has(k)) animatedProps.push(k);
              }
            }
          }
          const tp = anim.transitionProperty;
          if (tp && MOTION_PROPS.has(tp)) animatedProps.push(tp);
          animatedProps = [...new Set(animatedProps)];
          if (animatedProps.length > 0) {
            found.push({
              selector: selectorFor(target),
              actual: `running ${anim.constructor?.name || 'Animation'} (${animatedProps.join(',')}) during ${phase} under prefers-reduced-motion: reduce`,
              expected: 'no spatial transform/scale/rotate motion under reduced motion (opacity cross-fade allowed)',
            });
          }
        }
        return found;
      }, phaseLabel);

    const reducedMotionMap = new Map();
    const recordRM = (list) => {
      for (const v of list) {
        if (!reducedMotionMap.has(v.selector)) reducedMotionMap.set(v.selector, v);
      }
    };

    recordRM(await sampleMotionViolations('idle'));

    // Trigger hover + press on up to 3 visible pressable/interactive controls
    const pressTargets = await page.evaluate(() => {
      const els = Array.from(document.querySelectorAll('.cf-glass[data-pressable="true"], .cf-press, button:not([disabled])'))
        .filter((el) => {
          const cs = getComputedStyle(el);
          const r = el.getBoundingClientRect();
          return cs.display !== 'none' && cs.visibility !== 'hidden' && r.width > 0 && r.height > 0 && r.top >= 0 && r.bottom <= window.innerHeight;
        })
        .slice(0, 3);
      return els.map((el) => {
        const r = el.getBoundingClientRect();
        return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
      });
    });

    for (const pt of pressTargets) {
      await page.mouse.move(pt.x, pt.y);
      await page.mouse.down();
      await page.waitForTimeout(45);
      recordRM(await sampleMotionViolations('press'));
      await page.mouse.up();
      await page.waitForTimeout(45);
    }

    const reducedMotionViolations = Array.from(reducedMotionMap.values());

    const mkCheck = (id, basis, sourceToken, violations, okDetail) => ({
      id,
      status: violations.length === 0 ? 'PASS' : 'FAIL',
      basis,
      sourceToken,
      detail: violations.length === 0 ? okDetail : `${violations.length} violation(s)`,
      violations,
    });

    const glassOver = domData.glassNodes.length > domData.glassBudgetMax;
    const glassViolations = glassOver
      ? [{ selector: 'viewport', actual: `${domData.glassNodes.length} glass elements`, expected: `<= ${domData.glassBudgetMax}` }]
      : [];

    const contrastDetail =
      domData.contrastViolations.length === 0
        ? domData.contrastAdvisories.length > 0
          ? `All visible text meets HIG contrast floors (${domData.contrastAdvisories.length} Apple secondary-label advisory)`
          : 'All visible text meets HIG contrast floors'
        : `${domData.contrastViolations.length} violation(s)`;

    const checks = [
      mkCheck('font-size', 'measured', `typography.${platform === 'macos' ? 'macos' : 'iosLarge'}`, domData.fontViolations, 'All text matches type scale'),
      mkCheck('letter-spacing', 'measured', 'typography (trackingPx + nonLatin)', domData.trackingViolations, 'All tracking matches style scale / non-Latin zero'),
      mkCheck('border-radius', 'estimate-based', `shape.${platform === 'macos' ? 'radiusMacOS' : 'radiusIOS'}`, domData.radiusViolations, 'All radii match shape tokens or capsule'),
      mkCheck('spacing-grid', 'estimate-based', 'layout.spacing', domData.spacingViolations, 'All spacing aligns with 4px grid / spacing scale'),
      mkCheck('hit-target', 'official', `layout.hitTarget.${platform}`, domData.hitViolations, `All interactive controls >= ${domData.hitMin}px`),
      {
        id: 'contrast',
        status: domData.contrastViolations.length === 0 ? 'PASS' : 'FAIL',
        basis: 'official',
        sourceToken: 'tokens/color.json (HIG 4.5:1 / 3.0:1)',
        detail: contrastDetail,
        violations: domData.contrastViolations,
        ...(domData.contrastAdvisories.length > 0 ? { advisories: domData.contrastAdvisories } : {}),
      },
      mkCheck('glass-budget', 'estimate-based', 'materials.perfBudget.maxSimultaneousBackdrop', glassViolations, `${domData.glassNodes.length}/${domData.glassBudgetMax} simultaneous glass surfaces`),
      mkCheck(
        'glass-translucency',
        'official',
        'materials.liquidGlass (translucent outside reduce-transparency)',
        domData.glassTranslucencyViolations,
        domData.solidFallbackActive
          ? 'Skipped (reduce-transparency / high-contrast / forced-colors active)'
          : 'All glass surfaces retain translucency (alpha < 0.95)'
      ),
      mkCheck('focus-ring', 'measured', 'colors.focusRing', focusViolations, `${domData.unfocusedSnapshots.length} focusable control(s) retain visible focus ring`),
      mkCheck('raw-color', 'measured', 'colors + materials', domData.rawColorViolations, 'All colors resolve to token palette'),
      mkCheck('easing', 'estimate-based', 'motion.springs', domData.easingViolations, 'No forbidden ease/linear curves on active transitions/animations'),
      mkCheck('reduced-motion', 'official', 'motion (prefers-reduced-motion: reduce)', reducedMotionViolations, 'No spatial transform/scale/rotate animations active under prefers-reduced-motion: reduce'),
    ];

    const passCount = checks.filter((c) => c.status === 'PASS').length;
    const failCount = checks.filter((c) => c.status === 'FAIL').length;
    const totalAdvisories = checks.reduce((sum, c) => sum + (c.advisories?.length || 0), 0);
    const score = Math.round((passCount / checks.length) * 100);
    const scoreDisplay = totalAdvisories > 0 ? `${score} (${totalAdvisories} advisories)` : `${score}`;

    return {
      url: targetUrl,
      engine: engineName,
      platform,
      accent: tokens.$meta?.accent || null,
      summary: { pass: passCount, fail: failCount, notRun: 0, advisories: totalAdvisories, score, scoreDisplay },
      checks,
    };
  } finally {
    await browser.close().catch(() => {});
  }
}

function formatMarkdown(report) {
  const lines = [
    `# cupertino-forge Computed-Style QA Audit`,
    ``,
    `- **URL:** ${report.url}`,
    `- **Platform:** \`${report.platform}\`${report.engine ? ` (${report.engine})` : ''}`,
    `- **Score (Rule-Conformance DOM):** ${report.summary.score === null ? 'N/A (NOT RUN)' : `${report.summary.scoreDisplay ?? report.summary.score}/100`} (${report.summary.pass} PASS, ${report.summary.fail} FAIL, ${report.summary.notRun} NOT RUN${report.summary.advisories ? `, ${report.summary.advisories} advisories` : ''})`,
    ``,
    `| Check | Status | Basis | Detail | Token Source |`,
    `|---|---|---|---|---|`,
    ...report.checks.map((c) => `| \`${c.id}\` | **${c.status}** | \`${c.basis}\` | ${c.detail} | \`${c.sourceToken}\` |`),
  ];

  const withViolations = report.checks.filter((c) => c.violations.length > 0);
  if (withViolations.length > 0) {
    lines.push('', '## Violations');
    for (const c of withViolations) {
      lines.push('', `### \`${c.id}\` (${c.basis})`);
      for (const v of c.violations.slice(0, 15)) {
        lines.push(`- \`${v.selector}\`: actual \`${v.actual}\`, expected \`${v.expected}\``);
      }
      if (c.violations.length > 15) lines.push(`- ...and ${c.violations.length - 15} more`);
    }
  }
  return lines.join('\n') + '\n';
}

const opts = parseArgs(process.argv.slice(2));
const targetUrl = normalizeUrl(opts.url);
if (!targetUrl || !['ios', 'macos'].includes(opts.platform)) {
  process.stderr.write('Usage: node qa/computed-style-audit.mjs --url <url-or-file> [--tokens <resolved.json>] [--platform ios|macos] [--theme light|dark] [--accent <#HEX>] [--json] [--out <file>]\n');
  process.exit(2);
}

let cleanup = () => {};
try {
  const loaded = loadResolvedTokens(opts.tokens, opts.accent);
  cleanup = loaded.cleanup;
  if (opts.theme && !['light', 'dark'].includes(opts.theme)) {
    process.stderr.write('--theme must be light or dark\n');
    process.exit(2);
  }
  const report = await runAudit(targetUrl, loaded.tokens, opts.platform, opts.theme);
  report.theme = opts.theme || 'default';
  const rendered = opts.json ? JSON.stringify(report, null, 2) + '\n' : formatMarkdown(report);
  if (opts.out) fs.writeFileSync(path.resolve(opts.out), rendered, 'utf8');
  process.stdout.write(rendered);
  process.exit(report.summary.fail > 0 ? 1 : 0);
} catch (err) {
  process.stderr.write(`computed-style-audit error: ${err.message}\n`);
  process.exit(2);
} finally {
  cleanup();
}
